tool_input.command:
$sc = GET-Content 'D:\repository\skills\controller-bench\results\score-full.json' -Raw | ConvertFrom-Json
# 给每题打类别（cat 首两位）
function Get-Cat($t){ if($t -match '^(M\d)'){return $matches[1]} elseif($t -match '^T'){return 'T'} else {return '?'} }
$sc | Add-Member -NotePropertyName cat -NotePropertyValue ($sc | ForEach-Object { Get-Cat $_.task }) -Force
# 按模型×类别 求 total 平均 & ms 平均 & tool 平均
$rows = $sc | Group-Object model,cat | ForEach-Object {
  $g=$_.Group
  [pscustomobject]@{
    model=($g[0].model)
    cat=($g[0].cat)
    total=[math]::Round(($g.total|Measure-Object -Average).Average,3)
    tool=[math]::Round(($g.tool|Measure-Object -Average).Average,2)
    ms=[math]::Round(($g.ms|Measure-Object -Average).Average)
    n=$g.Count
  }
}
# 输出每类别下按 total 排序
foreach($c in 'M1','M2','M3','M4','M5','T'){
  Write-Output "=== $c ==="
  $rows | Where-Object cat -eq $c | Sort-Object total -Descending | ForEach-Object {
    Write-Output ("{0,-32} total={1,-6} tool={2,-5} ms={3,-6} n={4}" -f $_.model,$_.total,$_.tool,$_.ms,$_.n)
  }
}

