tool_input.command:
$sc = Get-Content 'D:\repository\skills\controller-bench\results\score-full.json' -Raw | ConvertFrom-Json
$rows = @()
foreach($grp in ($sc | Group-Object { if(([string]$_.task).StartsWith('T')){'T'}else{([string]$_.task).Substring(0,2)} }, { $_.model })){
  $g=$grp.Group; $n=$g.Count
  $cat = if(([string]$g[0].task).StartsWith('T')){'T'}else{([string]$g[0].task).Substring(0,2)}
  $sumT=0.0;$sumTool=0.0;$sumMs=0.0
  foreach($x in $g){ $sumT+=[double]$x.total; $sumTool+=[double]$x.tool; $sumMs+=[double]$x.ms }
  $rows += [pscustomobject]@{cat=$cat;model=$g[0].model;total=[math]::Round($sumT/$n,3);tool=[math]::Round($sumTool/$n,2);ms=[math]::Round($sumMs/$n)}
}
foreach($c in 'M1','M2','M3','M4','M5','T'){
  Write-Output "=== $c ==="
  $rows | Where-Object {$_.cat -eq $c} | Sort-Object total -Descending | ForEach-Object { Write-Output ("{0,-32} total={1,-6} tool={2,-5} ms={3,-6}" -f $_.model,$_.total,$_.tool,$_.ms) }
}

$sc = Get-Content 'D:\repository\skills\controller-bench\results\score-full.json' -Raw | ConvertFrom-Json
$cats = 'M1','M2','M3','M4','M5','T'
$models = ($sc | Group-Object model).Name
$result = @{}
foreach($m in $models){ foreach($c in $cats){ $result["$c|$m"] = @{ total=0.0;tool=0.0;ms=0.0;n=0 } } }
foreach($r in $sc){
  $t=[string]$r.task
  $c = if($t.StartsWith('T')){'T'} else {$t.Substring(0,2)}
  $e = $result["$c|$($r.model)"]
  $e.total += [double]$r.total; $e.tool += [double]$r.tool; $e.ms += [double]$r.ms; $e.n += 1
}
foreach($c in $cats){
  Write-Output "=== $c ==="
  $models | ForEach-Object {
    $e=$result["$c|$_"]; if($e.n -gt 0){
      [pscustomobject]@{model=$_;total=[math]::Round($e.total/$e.n,3);tool=[math]::Round($e.tool/$e.n,2);ms=[math]::Round($e.ms/$e.n)}
    }
  } | Sort-Object total -Descending | ForEach-Object { Write-Output ("{0,-32} total={1,-6} tool={2,-5} ms={3,-6}" -f $_.model,$_.total,$_.tool,$_.ms) }
}

$sc = Get-Content 'D:\repository\skills\controller-bench\results\score-full.json' -Raw | ConvertFrom-Json
function C($t){ if(([string]$t).StartsWith('T')){'T'}else{([string]$t).Substring(0,2)} }
# 给每条加 Cat 属性
