      ms=[math]::Round((($g|Measure-Object ms -Average).Average))
    }
  } | Sort-Object total -Descending | ForEach-Object { Write-Output ("{0,-32} total={1,-6} tool={2,-5} ms={3,-6}" -f $_.model,$_.total,$_.tool,$_.ms) }
}

